     9	typedef struct rb_node {
    10	    char *key; // Pointer to a copy of string key
    11	    void *value; // Pointer storing node's value
    12	    rb_color_t color; // Node's color
    13	    struct rb_node *parent; // Pointer towards parent node (Above)
    14	    struct rb_node *left; // Pointer towards the smaller child node
    15	    struct rb_node *right; // Pointer towards the larger child node
