    18	/* The concrete definition of the opaque `rbtree_t` from rbtree.h. Callers only
    19	 * ever hold a `struct rbtree *`, so every field here is private and may change
    20	 * without touching the graded contract in include/rbtree.h. One of these is
    21	 * allocated per tree by rb_create() and released by rb_destroy(). */
    22	struct rbtree {
    23	    /* Current root of the tree. Points at `nil` (never a raw NULL) when the tree
    24	     * is empty, so traversal and fixup code can treat an empty tree and a real
    25	     * subtree uniformly. Updated by insert/delete and by the rotation helpers. */
    26	    rb_node_t *root;
    27	
    28	    /* The single shared sentinel standing in for every NULL child and for the
    29	     * parent of the root. Allocated once in rb_create(); its `color` is always
    30	     * BLACK, and its key/value/child pointers are unused. Using one sentinel
    31	     * (rather than NULL) removes the null checks from the red-black fixup and
    32	     * lets delete-fixup temporarily write `nil->parent`. Must be freed exactly
    33	     * once, by rb_destroy(), after all real nodes are gone. */
    34	    rb_node_t *nil;
    35	
    36	    /* Caller-supplied destructor for owned values, captured from rb_create().
    37	     * May be NULL, meaning the tree does not own the values and must not free
    38	     * them. When non-NULL it is invoked on the old value when a key is
    39	     * overwritten by rb_insert(), on the removed value by rb_delete(), and on
    40	     * every remaining value by rb_destroy(). */
    41	    rb_value_free_fn value_free;
    42	
    43	    /* Number of key/value pairs currently stored (excludes the `nil` sentinel).
    44	     * Maintained incrementally: +1 on a successful insert of a new key, +0 when
    45	     * an insert overwrites an existing key, -1 on a successful delete. Returned
    46	     * as-is by rb_size(), which is therefore O(1). */
    47	    size_t size;
    48	};
