    50	/* Allocates an empty tree and its `nil` sentinel.
    51	 * `value_free` is stored verbatim; NULL means the tree does not own values.
    52	 * Returns NULL on allocation failure, having freed any partial allocation. */
    53	rbtree_t *rb_create(rb_value_free_fn value_free) {
    54	    rbtree_t *t = rb_malloc(sizeof *t);
    55	    if (t == NULL) {
    56	        return NULL;
    57	    }
    58	
    59	    rb_node_t *nil = rb_malloc(sizeof *nil);
    60	    if (nil == NULL) {
    61	        goto fail_tree;
    62	    }
    63	    /* The sentinel is always black; its links point at itself so that a stray
    64	     * traversal off a leaf terminates instead of dereferencing NULL. */
    65	    nil->key = NULL;
    66	    nil->value = NULL;
    67	    nil->color = BLACK;
    68	    nil->parent = nil;
    69	    nil->left = nil;
    70	    nil->right = nil;
    71	
    72	    t->nil = nil;
    73	    t->root = nil; /* empty tree: root == nil, never NULL */
    74	    t->value_free = value_free;
    75	    t->size = 0;
    76	    return t;
    77	
    78	fail_tree:
    79	    rb_free(t);
    80	    return NULL;
    81	}
