    83	/* Post-order free of one subtree. Depth is O(log n) for a valid RB tree. */
    84	static void rb_free_subtree(rbtree_t *t, rb_node_t *n) {
    85	    if (n == t->nil) {
    86	        return;
    87	    }
    88	    rb_free_subtree(t, n->left);
    89	    rb_free_subtree(t, n->right);
    90	    rb_free(n->key);
    91	    if (t->value_free != NULL) {
    92	        t->value_free(n->value);
    93	    }
    94	    rb_free(n);
    95	}
