    97	/* Frees every node, key copy, and (if owned) value, then the tree and its
    98	 * sentinel. NULL-safe per the contract. */
    99	void rb_destroy(rbtree_t *t) {
   100	    if (t == NULL) {
   101	        return;
   102	    }
   103	    rb_free_subtree(t, t->root);
   104	    rb_free(t->nil);
   105	    rb_free(t);
   106	}
