   113	/* Recursively checks the subtree rooted at n. Returns that subtree's
   114	 * black-height (black nodes on any n-to-nil path, counting the terminal nil),
   115	 * or -1 if any red-black or BST invariant is violated within it.
   116	 * invariant: on return *prev is the greatest key visited so far by the global
   117	 * in-order walk (NULL before the first key), and *count has been incremented
   118	 * once per real (non-nil) node visited so far.
   119	 * Assumes an acyclic tree; a corrupted cycle would recurse unboundedly (out of
   120	 * scope for this milestone). */
   121	static int rb_check(const rbtree_t *t, const rb_node_t *n,
   122	                    const char **prev, size_t *count) {
   123	    if (n == t->nil) {
   124	        return 1; /* terminal nil counts as one black node */
   125	    }
   126	
   127	    /* property 2: a red node must not have a red child (nil reads BLACK) */
   128	    if (n->color == RED &&
   129	        (n->left->color == RED || n->right->color == RED)) {
   130	        return -1;
   131	    }
   132	
   133	    int lh = rb_check(t, n->left, prev, count);
   134	    if (lh < 0) {
   135	        return -1;
   136	    }
   137	
   138	    /* property 4: in-order keys strictly increasing (checked at the in-order
   139	     * position, between the left and right recursion) */
   140	    if (*prev != NULL && strcmp(*prev, n->key) >= 0) {
   141	        return -1;
   142	    }
   143	    *prev = n->key;
   144	    *count += 1; /* property 5: count this real node */
   145	
   146	    int rh = rb_check(t, n->right, prev, count);
   147	    if (rh < 0) {
   148	        return -1;
   149	    }
   150	
   151	    /* property 3: both sides have equal black-height */
   152	    if (lh != rh) {
   153	        return -1;
   154	    }
   155	
   156	    return lh + (n->color == BLACK ? 1 : 0);
   157	}
