   159	/* Returns 0 iff all red-black invariants hold, -1 otherwise. */
   160	int rb_validate(const rbtree_t *t) {
   161	    if (t == NULL) {
   162	        return -1; /* a NULL tree is not a valid RB tree */
   163	    }
   164	
   165	    /* property 1: root is black. Empty tree: root == nil, which is BLACK, so
   166	     * the empty tree is accepted here too. */
   167	    if (t->root->color != BLACK) {
   168	        return -1;
   169	    }
   170	
   171	    const char *prev = NULL; /* greatest key seen by the in-order walk */
   172	    size_t count = 0;        /* real nodes seen by the walk */
   173	    if (rb_check(t, t->root, &prev, &count) < 0) {
   174	        return -1;
   175	    }
   176	
   177	    /* property 5: cached size matches the real node count */
   178	    if (count != t->size) {
   179	        return -1;
   180	    }
   181	
   182	    return 0;
   183	}
