   185	/* Heap copy of a NUL-terminated key; the tree owns the result. NULL on OOM.
   186	 * Not strdup(): under -std=c23 (strict) the glibc headers may not declare it,
   187	 * and an implicit declaration would trip -Werror. */
   188	static char *dup_key(const char *key) {
   189	    size_t n = strlen(key) + 1;
   190	    char *copy = rb_malloc(n);
   191	    if (copy == NULL) {
   192	        return NULL;
   193	    }
   194	    memcpy(copy, key, n);
   195	    return copy;
   196	}
