   198	/* CLRS left rotation, sentinel form. Assumes x->right != t->nil. Retargets
   199	 * t->root when x was the root. */
   200	static void left_rotate(rbtree_t *t, rb_node_t *x) {
   201	    rb_node_t *y = x->right; /* y takes x's slot; x becomes y->left */
   202	    x->right = y->left;
   203	    if (y->left != t->nil) {
   204	        y->left->parent = x;
   205	    }
   206	    y->parent = x->parent;
   207	    if (x->parent == t->nil) {
   208	        t->root = y;
   209	    } else if (x == x->parent->left) {
   210	        x->parent->left = y;
   211	    } else {
   212	        x->parent->right = y;
   213	    }
   214	    y->left = x;
   215	    x->parent = y;
   216	}
   217	
   218	/* Mirror of left_rotate. Assumes x->left != t->nil. */
   219	static void right_rotate(rbtree_t *t, rb_node_t *x) {
   220	    rb_node_t *y = x->left; /* y takes x's slot; x becomes y->right */
   221	    x->left = y->right;
   222	    if (y->right != t->nil) {
   223	        y->right->parent = x;
   224	    }
   225	    y->parent = x->parent;
   226	    if (x->parent == t->nil) {
   227	        t->root = y;
   228	    } else if (x == x->parent->right) {
   229	        x->parent->right = y;
   230	    } else {
   231	        x->parent->left = y;
   232	    }
   233	    y->right = x;
   234	    x->parent = y;
   235	}
