   237	/* CLRS RB-INSERT-FIXUP. z is the freshly linked RED node; restore the red-black
   238	 * invariants by recoloring and rotating up the tree. */
   239	static void rb_insert_fixup(rbtree_t *t, rb_node_t *z) {
   240	    /* invariant: z is RED; the only invariant that can be broken is a red z
   241	     * with a red parent. When z is the root, z->parent is t->nil (BLACK) and
   242	     * the loop exits immediately. */
   243	    while (z->parent->color == RED) {
   244	        if (z->parent == z->parent->parent->left) {
   245	            rb_node_t *uncle = z->parent->parent->right;
   246	            if (uncle->color == RED) {
   247	                /* case 1: red uncle -> recolor and move up */
   248	                z->parent->color = BLACK;
   249	                uncle->color = BLACK;
   250	                z->parent->parent->color = RED;
   251	                z = z->parent->parent;
   252	            } else {
   253	                if (z == z->parent->right) {
   254	                    /* case 2: triangle -> rotate to a line */
   255	                    z = z->parent;
   256	                    left_rotate(t, z);
   257	                }
   258	                /* case 3: line -> recolor and rotate the grandparent */
   259	                z->parent->color = BLACK;
   260	                z->parent->parent->color = RED;
   261	                right_rotate(t, z->parent->parent);
   262	            }
   263	        } else {
   264	            /* mirror image: parent is a right child */
   265	            rb_node_t *uncle = z->parent->parent->left;
   266	            if (uncle->color == RED) {
   267	                z->parent->color = BLACK;
   268	                uncle->color = BLACK;
   269	                z->parent->parent->color = RED;
   270	                z = z->parent->parent;
   271	            } else {
   272	                if (z == z->parent->left) {
   273	                    z = z->parent;
   274	                    right_rotate(t, z);
   275	                }
   276	                z->parent->color = BLACK;
   277	                z->parent->parent->color = RED;
   278	                left_rotate(t, z->parent->parent);
   279	            }
   280	        }
   281	    }
   282	    t->root->color = BLACK;
   283	}
