   285	/* Inserts or overwrites key. On success (return 0) the tree owns value; on any
   286	 * failure (return -1) the tree is unchanged and value is NOT consumed. */
   287	int rb_insert(rbtree_t *t, const char *key, void *value) {
   288	    if (t == NULL || key == NULL) {
   289	        return -1; /* invalid args: tree unchanged, value NOT consumed */
   290	    }
   291	
   292	    /* phase 1: read-only BST descent, remembering the parent and last compare.
   293	     * invariant: key, if present, is in the subtree rooted at cur; parent is
   294	     * cur's parent. */
